CREATE TRIGGER run_recovery_documents_claim_generation BEFORE UPDATE OF state ON run_recovery_documents WHEN OLD.state='pending' AND NEW.state='dispatching' AND NOT EXISTS ( SELECT 1 FROM run_recoveries p JOIN runs r ON r.id=p.run_id JOIN documents d ON d.run_id=r.id AND d.fingerprint=OLD.fingerprint WHERE p.id=OLD.recovery_id AND r.status='running' AND p.generation=(SELECT MAX(generation) FROM run_recoveries WHERE run_id=r.id) AND d.workflow_id=OLD.new_workflow_id ) BEGIN SELECT RAISE(ABORT,'The continuation reservation is no longer active'); END;
